"""Página HTML da interface operacional local."""

HTML = r"""<!doctype html>
<html lang="pt-BR" data-theme="dark">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="dark light">
<title>Candidatura Agent — Operação</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Doto:wght@500&family=Space+Grotesk:wght@400;500&family=Space+Mono:wght@400;700&display=swap" rel="stylesheet">
<script>
(()=>{const saved=localStorage.getItem('ca-theme');const hour=new Date().getHours();document.documentElement.dataset.theme=saved||(hour>=7&&hour<19?'light':'dark')})();
</script>
<style>
:root{--bg:#000;--surface:#111;--raised:#1a1a1a;--border:#222;--border-visible:#333;--disabled:#666;--secondary:#999;--primary:#e8e8e8;--display:#fff;--accent:#d71921;--accent-subtle:#2a0507;--success:#4a9e5c;--warning:#c41a1a;--interactive:#5b9bf6;--display-font:'Doto','Space Mono',monospace;--body-font:'Space Grotesk',system-ui,sans-serif;--mono-font:'Space Mono',ui-monospace,monospace;--display-size:clamp(64px,9vw,112px);--body-size:clamp(17px,1.8vw,24px);--label-size:11px;color-scheme:dark}
html[data-theme='light']{--bg:#f5f5f5;--surface:#fff;--raised:#f0f0f0;--border:#e8e8e8;--border-visible:#ccc;--disabled:#999;--secondary:#666;--primary:#1a1a1a;--display:#000;--accent-subtle:#fdeaea;--interactive:#006ad6;color-scheme:light}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--primary);font-family:var(--body-font);font-size:16px;line-height:1.4}button,input,select{font:inherit}button,a,input,select{outline:none}:focus-visible{outline:2px solid var(--display);outline-offset:3px}button{color:inherit}.shell{width:min(1440px,calc(100% - 64px));margin:auto}.topbar{min-height:72px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:16px}.brand{font-family:var(--mono-font);font-size:var(--label-size);letter-spacing:.12em;text-transform:uppercase;color:var(--display)}.brand b{color:var(--accent)}.live{display:flex;align-items:center;gap:8px;margin-left:12px;color:var(--secondary);font-family:var(--mono-font);font-size:var(--label-size);letter-spacing:.08em;text-transform:uppercase}.live-dot{width:7px;height:7px;background:var(--success);border-radius:50%}.spacer{flex:1}.technical-button{min-height:44px;padding:0 18px;border:1px solid var(--border-visible);border-radius:999px;background:transparent;color:var(--secondary);font-family:var(--mono-font);font-size:var(--label-size);letter-spacing:.08em;text-transform:uppercase;cursor:pointer;transition:color .16s ease-out,border-color .16s ease-out,background .16s ease-out}.technical-button:hover{border-color:var(--display);color:var(--display)}.technical-button.primary{background:var(--display);border-color:var(--display);color:var(--bg)}#refresh{min-width:132px}.technical-button:disabled{opacity:.4;cursor:default}.hero{min-height:460px;padding:72px 0 64px;display:grid;grid-template-columns:minmax(0,1.25fr) minmax(300px,.75fr);gap:96px;align-items:end}.label{font-family:var(--mono-font);font-size:var(--label-size);line-height:1.2;letter-spacing:.12em;text-transform:uppercase;color:var(--secondary)}.hero-number{display:flex;align-items:baseline;gap:10px;margin:18px 0 6px;color:var(--display);font-family:var(--display-font);font-size:var(--display-size);font-weight:500;line-height:.82;letter-spacing:-.04em}.hero-number small{font-family:var(--mono-font);font-size:var(--body-size);letter-spacing:0;color:var(--secondary)}.hero-copy{max-width:540px;margin:22px 0 0;font-size:var(--body-size);line-height:1.22;color:var(--primary)}.progress-meta{display:flex;justify-content:space-between;gap:16px;margin-top:40px}.segments{display:grid;grid-template-columns:repeat(10,1fr);gap:4px;margin-top:10px}.segment{height:10px;background:var(--border)}.segment.filled{background:var(--display)}.segment.over{background:var(--accent)}.status-stack{border-top:1px solid var(--border-visible)}.status-row{min-height:58px;border-bottom:1px solid var(--border);display:grid;grid-template-columns:1fr auto;align-items:center;gap:24px}.status-row span{font-family:var(--mono-font);font-size:var(--label-size);letter-spacing:.1em;text-transform:uppercase;color:var(--secondary)}.status-row b{font-family:var(--mono-font);font-size:var(--body-size);font-weight:400;color:var(--display)}.status-row b.bad{color:var(--accent)}.status-row b.good{color:var(--success)}.queue{padding:64px 0 96px;border-top:1px solid var(--border)}.section-head{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:32px;align-items:end;margin-bottom:48px}.section-head h1,.detail-title{max-width:760px;margin:10px 0 0;color:var(--display);font-size:var(--body-size);font-weight:500;line-height:1.15;letter-spacing:-.025em}.system-line{display:flex;align-items:center;gap:16px;justify-content:flex-end;flex-wrap:wrap}.inline-state{min-width:150px;text-align:right}.filters{display:grid;grid-template-columns:2fr 1fr 1fr .75fr;gap:16px;margin-bottom:40px}.field label{display:block;margin-bottom:9px}.field input,.field select{width:100%;height:48px;padding:0 4px;border:0;border-bottom:1px solid var(--border-visible);border-radius:0;background:transparent;color:var(--display);font-family:var(--mono-font);font-size:13px}.field input:focus,.field select:focus{border-bottom-color:var(--display)}.field input::placeholder{color:var(--disabled)}.job-list{border-top:1px solid var(--border-visible)}.job-row{width:100%;min-height:106px;padding:20px 0;border:0;border-bottom:1px solid var(--border);background:transparent;display:grid;grid-template-columns:48px minmax(0,1fr) minmax(140px,.35fr) 88px;gap:24px;align-items:center;text-align:left;cursor:pointer;transition:background .16s ease-out}.job-row:hover,.job-row:focus-visible{background:var(--surface)}.job-index{font-family:var(--mono-font);font-size:var(--label-size);color:var(--disabled)}.job-title{display:block;color:var(--display);font-size:var(--body-size);font-weight:500;line-height:1.15}.job-company{display:block;margin-top:7px;color:var(--secondary);font-size:13px}.tags{display:flex;gap:6px;flex-wrap:wrap}.tag{display:inline-block;padding:5px 9px;border:1px solid var(--border-visible);border-radius:4px;font-family:var(--mono-font);font-size:10px;line-height:1;letter-spacing:.08em;text-transform:uppercase;color:var(--secondary)}.tag.good{color:var(--success)}.tag.bad{border-color:var(--accent);color:var(--accent)}.job-score{text-align:right;color:var(--display);font-family:var(--mono-font);font-size:var(--body-size)}.job-score small{display:block;margin-top:4px;color:var(--disabled);font-size:9px;letter-spacing:.1em}.pager{display:flex;align-items:center;gap:12px;margin-top:32px}.pager .inline-state{text-align:center;min-width:130px}.empty{padding:96px 0;text-align:center;color:var(--secondary)}.empty .label{display:block;margin-top:10px;color:var(--disabled)}.detail-wrap{padding:56px 0 96px}.back{width:44px;height:44px;border:1px solid var(--border-visible);border-radius:50%;background:var(--surface);color:var(--display);font-family:var(--mono-font);cursor:pointer}.detail-hero{padding:56px 0 64px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:64px;align-items:end}.detail-title{font-size:clamp(30px,5vw,62px);max-width:920px}.detail-company{margin-top:18px;color:var(--secondary);font-size:var(--body-size)}.detail-score{font-family:var(--display-font);font-size:clamp(44px,5vw,64px);line-height:.8;color:var(--display);text-align:right}.detail-score small{display:block;margin-top:14px;font-family:var(--mono-font);font-size:var(--label-size);letter-spacing:.1em;color:var(--secondary)}.detail-grid{display:grid;grid-template-columns:minmax(300px,.75fr) minmax(0,1.25fr);gap:80px;border-top:1px solid var(--border-visible);padding-top:48px}.data-row{padding:15px 0;border-bottom:1px solid var(--border);display:grid;grid-template-columns:120px minmax(0,1fr);gap:20px}.data-row dt{font-family:var(--mono-font);font-size:var(--label-size);text-transform:uppercase;letter-spacing:.08em;color:var(--secondary)}.data-row dd{margin:0;color:var(--primary);overflow-wrap:anywhere}.data-row a{color:var(--interactive)}.feedback{margin-top:48px}.feedback-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}.feedback input{width:100%;height:48px;padding:0 4px;border:0;border-bottom:1px solid var(--border-visible);background:transparent;color:var(--display);font-family:var(--mono-font);font-size:13px}.feedback-status{display:block;min-height:18px;margin-top:12px}.audit-head{display:flex;align-items:end;gap:16px;margin-bottom:16px}.audit-head .spacer{min-width:20px}.event{display:grid;grid-template-columns:132px 140px minmax(0,1fr);gap:18px;padding:15px 0;border-bottom:1px solid var(--border);font-family:var(--mono-font);font-size:11px;line-height:1.5}.event time{color:var(--disabled)}.event-kind{color:var(--accent);text-transform:uppercase}.event-payload{color:var(--secondary);overflow-wrap:anywhere}.more-events{margin-top:24px}.loading{padding:64px 0;color:var(--secondary);font-family:var(--mono-font);font-size:var(--label-size);letter-spacing:.1em;text-transform:uppercase}@media(max-width:900px){.shell{width:min(100% - 40px,1440px)}.hero{grid-template-columns:1fr;gap:56px;min-height:0;padding-top:64px}.filters{grid-template-columns:1fr 1fr}.job-row{grid-template-columns:36px minmax(0,1fr) 72px}.job-row .tags{grid-column:2/4}.detail-grid{grid-template-columns:1fr;gap:64px}.detail-hero{grid-template-columns:1fr}.detail-score{text-align:left}}@media(max-width:560px){.shell{width:min(100% - 28px,1440px)}.topbar{min-height:64px}.live{display:none}.technical-button{padding:0 13px}.hero{padding:56px 0}.hero-copy{margin-top:18px}.filters{grid-template-columns:1fr}.section-head{grid-template-columns:1fr;align-items:start}.system-line{justify-content:flex-start}.inline-state{text-align:left}.job-row{grid-template-columns:28px minmax(0,1fr) 58px;gap:12px}.job-row>span:nth-child(2){grid-column:2;grid-row:1}.job-row .tags{grid-column:2/4;grid-row:2}.job-score{grid-column:3;grid-row:1;align-self:start}.job-company{font-size:12px}.detail-wrap{padding-top:32px}.detail-hero{padding:40px 0}.data-row{grid-template-columns:1fr;gap:7px}.event{grid-template-columns:1fr;gap:5px}.pager{justify-content:space-between}.pager .technical-button{font-size:0;width:44px;padding:0}.pager .technical-button:first-child:after{content:'←';font-size:14px}.pager .technical-button:last-child:after{content:'→';font-size:14px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}
</style>
</head>
<body>
<header><div class="shell topbar"><div class="brand"><b>●</b> CA / OPS</div><div class="live"><span class="live-dot"></span>Sistema local</div><span class="spacer"></span><button class="technical-button" id="theme-toggle" onclick="toggleTheme()">[ TEMA ]</button><button class="technical-button primary" id="refresh" onclick="refreshAll()">Atualizar</button></div></header>
<main class="shell">
<div id="list-view">
<section class="hero" aria-labelledby="hero-label"><div><div class="label" id="hero-label">Meta mínima de hoje</div><div class="hero-number"><span id="submitted">—</span><small id="target">/ —</small></div><p class="hero-copy" id="hero-copy">[ CARREGANDO OPERAÇÃO ]</p><div class="progress-meta"><span class="label">Progresso diário</span><span class="label" id="progress-label">—</span></div><div class="segments" id="segments" aria-hidden="true"></div></div><div class="status-stack" id="stats"><div class="loading">[ CARREGANDO ESTADOS ]</div></div></section>
<section class="queue"><div class="section-head"><div><div class="label">Fila operacional</div><h1>O que merece atenção agora.</h1></div><div class="system-line"><span class="label inline-state" id="updated">[ CARREGANDO ]</span></div></div><div class="filters"><div class="field"><label class="label" for="f-q">Título ou empresa</label><input id="f-q" placeholder="Comece a digitar" oninput="debouncedLoad()"></div><div class="field"><label class="label" for="f-status">Estado</label><select id="f-status" onchange="resetAndLoad()"><option value="">Todos</option><option>qualified</option><option>blocked</option><option>new</option><option>submitted</option><option>rejected</option><option>dry_run</option></select></div><div class="field"><label class="label" for="f-ats">ATS</label><select id="f-ats" onchange="resetAndLoad()"><option value="">Todos</option><option>greenhouse</option><option>ashby</option><option>lever</option><option>gupy</option><option>workday</option><option>smartrecruiters</option><option>factorial</option><option>recruitee</option><option>workable</option><option>teamtailor</option></select></div><div class="field"><label class="label" for="f-min">Score mínimo</label><input id="f-min" type="number" min="0" max="100" placeholder="0–100" oninput="debouncedLoad()"></div></div><section class="job-list" id="jobs" aria-live="polite"><div class="loading">[ CARREGANDO FILA ]</div></section><div class="pager"><button class="technical-button" id="page-prev" onclick="changePage(-1)">← Anterior</button><span class="label inline-state" id="page-label">—</span><button class="technical-button" id="page-next" onclick="changePage(1)">Próxima →</button></div></section>
</div>
<section id="detail-view" style="display:none" aria-live="polite"></section>
</main>
<script>
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const parseList=k=>{if(Array.isArray(k))return k;try{const v=JSON.parse(k||'[]');return Array.isArray(v)?v:[]}catch{return []}};
const safeUrl=value=>{try{const u=new URL(String(value||''),window.location.origin);return ['http:','https:'].includes(u.protocol)?u.href:'#'}catch{return '#'}};
const statusClass=status=>['blocked','rejected'].includes(status)?'bad':['qualified','submitted'].includes(status)?'good':'';
let debounceT=null,pageOffset=0,currentEvents=[],visibleEvents=30;const PAGE_SIZE=20;
function applyThemeLabel(){const theme=document.documentElement.dataset.theme;document.getElementById('theme-toggle').textContent=theme==='dark'?'[ DARK ]':'[ LIGHT ]'}
function toggleTheme(){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('ca-theme',next);applyThemeLabel()}
function debouncedLoad(){clearTimeout(debounceT);pageOffset=0;debounceT=setTimeout(loadJobs,300)}
function resetAndLoad(){pageOffset=0;loadJobs()}
function changePage(direction){pageOffset=Math.max(0,pageOffset+direction*PAGE_SIZE);loadJobs();document.querySelector('.queue').scrollIntoView({behavior:'smooth'})}
function qs(){const p=new URLSearchParams({limit:String(PAGE_SIZE),offset:String(pageOffset)});const q=document.getElementById('f-q').value.trim();if(q)p.set('q',q);const s=document.getElementById('f-status').value;if(s)p.set('status',s);const a=document.getElementById('f-ats').value;if(a)p.set('ats',a);const m=document.getElementById('f-min').value;if(m)p.set('min_score',m);return p.toString()}
function renderSegments(submitted,minimum){const total=10,ratio=minimum?submitted/minimum:0,filled=Math.min(total,Math.round(ratio*total));document.getElementById('segments').innerHTML=Array.from({length:total},(_,i)=>`<span class="segment ${i<filled?'filled':''} ${ratio>1&&i===total-1?'over':''}"></span>`).join('');document.getElementById('progress-label').textContent=`${Math.round(ratio*100)}%`}
async function loadSnapshot(){const d=await fetch('/api/snapshot').then(r=>{if(!r.ok)throw new Error('snapshot');return r.json()});const submitted=d.daily_target.submitted,minimum=d.daily_target.minimum,gap=d.daily_target.gap;document.getElementById('submitted').textContent=submitted;document.getElementById('target').textContent=`/ ${minimum}`;document.getElementById('hero-copy').textContent=d.daily_target.met?'Meta cumprida. O sistema segue sem teto artificial.':`Faltam ${gap} candidatura${gap===1?'':'s'} para o mínimo. Sem chute, sem campo bloqueante.`;renderSegments(submitted,minimum);const rows=[['submitted','enviadas'],['qualified','qualificadas'],['blocked','bloqueadas'],['new','novas'],['dry_run','simuladas'],['rejected','rejeitadas']];document.getElementById('stats').innerHTML=rows.map(([key,label])=>`<div class="status-row"><span>${label}</span><b class="${statusClass(key)}">${d.stats[key]||0}</b></div>`).join('');document.getElementById('updated').textContent=`ATUALIZADO ${new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}`}
async function loadJobs(){const d=await fetch('/api/jobs?'+qs()).then(r=>{if(!r.ok)throw new Error('jobs');return r.json()});const start=d.count?pageOffset+1:0,end=Math.min(pageOffset+PAGE_SIZE,d.count);document.getElementById('page-label').textContent=`${start}–${end} / ${d.count}`;document.getElementById('page-prev').disabled=pageOffset===0;document.getElementById('page-next').disabled=pageOffset+PAGE_SIZE>=d.count;document.getElementById('jobs').innerHTML=d.jobs.length?d.jobs.map((j,index)=>{const blockers=parseList(j.blockers),cls=statusClass(j.status);return `<button class="job-row" onclick="openDetail(${j.id})"><span class="job-index">${String(pageOffset+index+1).padStart(3,'0')}</span><span><span class="job-title">${esc(j.title)}</span><span class="job-company">${esc(j.company)} · ${esc(j.location)}</span></span><span class="tags"><span class="tag ${cls}">${esc(j.status)}</span>${j.ats?`<span class="tag">${esc(j.ats)}</span>`:''}${blockers.length?`<span class="tag bad">${blockers.length} bloqueio${blockers.length===1?'':'s'}</span>`:''}</span><span class="job-score">${j.fit_score}<small>/ 100</small></span></button>`}).join(''):'<div class="empty">Nada aqui.<span class="label">Troque os filtros e tente de novo.</span></div>'}
function renderEvents(){const events=currentEvents.slice(0,visibleEvents);document.getElementById('events').innerHTML=events.length?events.map(e=>`<div class="event"><time>${esc(e.created_at)}</time><span class="event-kind">${esc(e.kind)}</span><span class="event-payload">${esc(e.payload)}</span></div>`).join(''):'<div class="empty">Sem eventos.<span class="label">Ainda não há trilha para esta vaga.</span></div>';const more=document.getElementById('more-events');more.style.display=visibleEvents<currentEvents.length?'inline-block':'none';more.textContent=`Mostrar mais (${currentEvents.length-visibleEvents})`}
function showMoreEvents(){visibleEvents+=30;renderEvents()}
async function openDetail(id){const [d,ev]=await Promise.all([fetch('/api/jobs/'+id).then(r=>r.json()),fetch('/api/jobs/'+id+'/events').then(r=>r.json())]);const j=d.job,blockers=parseList(j.blockers),reasons=parseList(j.fit_reasons);currentEvents=ev.events;visibleEvents=30;document.getElementById('list-view').style.display='none';const detail=document.getElementById('detail-view');detail.style.display='block';detail.innerHTML=`<div class="detail-wrap"><button class="back" onclick="closeDetail()" aria-label="Voltar">←</button><div class="detail-hero"><div><div class="label">Vaga #${j.id} · ${esc(j.status)}</div><h1 class="detail-title">${esc(j.title)}</h1><div class="detail-company">${esc(j.company)} · ${esc(j.location)}</div></div><div class="detail-score">${j.fit_score}<small>FIT / 100</small></div></div><div class="detail-grid"><div><dl><div class="data-row"><dt>Estado</dt><dd>${esc(j.status)}</dd></div><div class="data-row"><dt>ATS</dt><dd>${esc(j.ats||'—')}</dd></div><div class="data-row"><dt>Motivos</dt><dd>${reasons.length?reasons.map(esc).join(' · '):'—'}</dd></div><div class="data-row"><dt>Bloqueios</dt><dd>${blockers.length?blockers.map(esc).join(' · '):'Nenhum'}</dd></div><div class="data-row"><dt>Criada</dt><dd>${esc(j.created_at)}</dd></div><div class="data-row"><dt>Atualizada</dt><dd>${esc(j.updated_at)}</dd></div><div class="data-row"><dt>Origem</dt><dd><a href="${esc(safeUrl(j.source_url))}" target="_blank" rel="noreferrer">Abrir anúncio ↗</a></dd></div>${j.apply_url?`<div class="data-row"><dt>Candidatura</dt><dd><a href="${esc(safeUrl(j.apply_url))}" target="_blank" rel="noreferrer">Abrir formulário ↗</a></dd></div>`:''}</dl><div class="feedback"><div class="label">Ensine o ranking</div><input id="reason-${j.id}" placeholder="Motivo opcional"><div class="feedback-actions"><button class="technical-button" onclick="sendFeedback(${j.id},'good')">Boa</button><button class="technical-button" onclick="sendFeedback(${j.id},'bad')">Ruim</button><button class="technical-button" onclick="sendFeedback(${j.id},'irrelevant')">Irrelevante</button></div><span class="label feedback-status" id="feedback-status"></span></div></div><div><div class="audit-head"><div><div class="label">Auditoria</div><div class="section-head-title">${ev.events.length} eventos registrados</div></div><span class="spacer"></span><span class="label">Mais recentes primeiro</span></div><div id="events"></div><button class="technical-button more-events" id="more-events" onclick="showMoreEvents()"></button></div></div></div>`;renderEvents();window.scrollTo({top:0,behavior:'instant'})}
function closeDetail(){document.getElementById('detail-view').style.display='none';document.getElementById('list-view').style.display='block';window.scrollTo({top:0,behavior:'instant'})}
async function sendFeedback(id,rating){const status=document.getElementById('feedback-status'),reason=document.getElementById('reason-'+id).value;status.textContent='[ SALVANDO ]';const response=await fetch('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:id,rating,reason})});status.textContent=response.ok?'[ SALVO ]':'[ ERRO AO SALVAR ]';if(response.ok)await loadSnapshot()}
async function refreshAll(){const button=document.getElementById('refresh');button.disabled=true;button.textContent='[ ATUALIZANDO ]';try{await Promise.all([loadSnapshot(),loadJobs()])}finally{button.disabled=false;button.textContent='Atualizar'}}
applyThemeLabel();refreshAll();setInterval(()=>{if(document.getElementById('list-view').style.display!=='none')refreshAll()},30000);
</script>
</body>
</html>"""
